/* Lightweight phrase-join checks. Suggests fades, never certifies musical compatibility. */
(function(root){
 function windowStats(channels,start,end){const length=channels[0].length,a=Math.max(0,Math.min(length-1,Math.floor(start))),b=Math.max(a+1,Math.min(length,Math.floor(end)));let sum=0,delta=0,n=0;const stride=Math.max(1,Math.floor((b-a)/2048));for(const ch of channels){for(let i=a+stride;i<b;i+=stride){const v=ch[i];sum+=v*v;delta+=Math.abs(v-ch[i-stride]);n++}}return {rms:Math.sqrt(sum/Math.max(1,n)),change:delta/Math.max(1,n)}}
 function suggest(channels,from,to,sampleRate,bpm,beats){const bar=60/bpm*beats,span=Math.max(1,Math.floor(.15*sampleRate));const a=windowStats(channels,from.end-span,from.end),b=windowStats(channels,to.start,to.start+span);const db=20*Math.log10((a.rms+1e-5)/(b.rms+1e-5));const change=Math.max(a.change,b.change);const sec=Math.min((from.end-from.start)/sampleRate/3,(to.end-to.start)/sampleRate/3,Math.max(.08,Math.min(.75,bar*.125+(Math.abs(db)>5?.2:0))));const issues=[];if(Math.abs(db)>5)issues.push('level difference');if(change>.16)issues.push('strong transient near join');if(from.end-from.start<bar*sampleRate*.98||to.end-to.start<bar*sampleRate*.98)issues.push('short phrase');return {exit:'bar',crossfade:Math.round(sec*100)/100,fadeCurve:'equal_power',levelDifferenceDb:Math.round(db*10)/10,issues,confidence:issues.length?'review':'candidate'} }
 const api={suggest,windowStats};if(typeof module!=='undefined')module.exports=api;else root.PulseJoin=api;
})(globalThis);
